{
  "openapi": "3.1.0",
  "info": {
    "title": "places",
    "version": "1.0.0"
  },
  "paths": {
    "/places": {
      "get": {
        "operationId": "places_get_places",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "required": [
                      "id",
                      "name",
                      "latitude",
                      "longitude"
                    ],
                    "properties": {
                      "id": {
                        "type": "string",
                        "enum": [
                          "oslo",
                          "helsinki",
                          "lisbon"
                        ]
                      },
                      "name": {
                        "type": "string"
                      },
                      "latitude": {
                        "type": "number",
                        "minimum": -90,
                        "maximum": 90
                      },
                      "longitude": {
                        "type": "number",
                        "minimum": -180,
                        "maximum": 180
                      }
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "500"
          }
        }
      },
      "post": {
        "operationId": "places_post_places",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "id",
                    "name",
                    "latitude",
                    "longitude"
                  ],
                  "properties": {
                    "id": {
                      "type": "string",
                      "enum": [
                        "oslo",
                        "helsinki",
                        "lisbon"
                      ]
                    },
                    "name": {
                      "type": "string"
                    },
                    "latitude": {
                      "type": "number",
                      "minimum": -90,
                      "maximum": 90
                    },
                    "longitude": {
                      "type": "number",
                      "minimum": -180,
                      "maximum": 180
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "400",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          },
          "415": {
            "description": "415"
          },
          "500": {
            "description": "500"
          }
        },
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "cityId"
                ],
                "additionalProperties": false,
                "properties": {
                  "cityId": {
                    "type": "string",
                    "enum": [
                      "oslo",
                      "helsinki",
                      "lisbon"
                    ]
                  }
                }
              }
            }
          }
        }
      }
    },
    "/places/{id}/refresh": {
      "post": {
        "operationId": "places_post_places_id_refresh",
        "responses": {
          "202": {
            "description": "202",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "placeId",
                    "status"
                  ],
                  "properties": {
                    "placeId": {
                      "type": "string"
                    },
                    "status": {
                      "const": "QUEUED"
                    }
                  }
                }
              }
            }
          },
          "404": {
            "description": "404",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          },
          "500": {
            "description": "500"
          }
        },
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string",
              "enum": [
                "oslo",
                "helsinki",
                "lisbon"
              ]
            }
          }
        ]
      }
    },
    "/health": {
      "get": {
        "operationId": "places_get_health",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "database": {
                      "const": "READY"
                    },
                    "kafka": {
                      "const": "READY"
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "500"
          }
        }
      }
    },
    "/openapi.json": {
      "get": {
        "operationId": "places_get_openapi.json",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "additionalProperties": true
                }
              }
            }
          },
          "500": {
            "description": "500"
          }
        }
      }
    }
  }
}
